<script setup lang="ts">
import * as echarts from "echarts";
import { onBeforeUnmount, onMounted, ref } from "vue";
import type { Talent } from "../data/mockReport";
const props=defineProps<{talents:Talent[]}>(); const host=ref<HTMLDivElement>(); let chart:echarts.ECharts|undefined,observer:ResizeObserver|undefined;
onMounted(()=>{if(!host.value)return;chart=echarts.init(host.value);const evidenceAmount=(t:Talent)=>Math.min(5,1+t.evidence.length*1.1+t.evidence.filter(item=>item.level==="strong").length*.35);chart.setOption({backgroundColor:"transparent",animationDuration:650,radar:{center:["50%","51%"],radius:"62%",splitNumber:5,indicator:props.talents.map(t=>({name:t.adultName,max:5})),axisName:{color:"#7A4E2D",fontSize:12,fontFamily:'"LXGW WenKai","Microsoft YaHei",sans-serif'},splitArea:{areaStyle:{color:["rgba(247,217,126,.06)","rgba(247,217,126,.13)"]}},splitLine:{lineStyle:{color:"rgba(122,78,45,.18)",width:1}},axisLine:{lineStyle:{color:"rgba(122,78,45,.18)"}}},series:[{type:"radar",symbol:"circle",symbolSize:7,lineStyle:{color:"#D68C91",width:2},itemStyle:{color:(params:any)=>props.talents[params.dataIndex%props.talents.length]?.color||"#F2A6B3",shadowBlur:8,shadowColor:"rgba(232,182,76,.45)"},areaStyle:{color:new echarts.graphic.RadialGradient(.5,.45,.7,[{offset:0,color:"rgba(242,166,179,.38)"},{offset:.55,color:"rgba(143,203,232,.23)"},{offset:1,color:"rgba(168,224,201,.08)"}])},data:[{value:props.talents.map(evidenceAmount)}]}]});observer=new ResizeObserver(()=>chart?.resize());observer.observe(host.value)});onBeforeUnmount(()=>{observer?.disconnect();chart?.dispose()});
</script>
<template><div ref="host" class="radar-chart" role="img" aria-label="六类智能阶段性采集证据数量分布图，不代表能力强弱"></div></template>
